def all_walks(vertices, edges, maxlen):
    """Enumerate all walks with <= maxlen edges; return set of frozenset edge-coverages."""
    adj = {}
    for (u, v) in edges:
        adj.setdefault(u, []).append(v)
    results = set()
    def rec(cur, covered, depth):
        results.add(frozenset(covered))
        if depth == maxlen:
            return
        for nxt in adj.get(cur, ()):
            e = (cur, nxt)
            covered.add(e)
            rec(nxt, covered, depth + 1)
            covered.discard(e)
    for s in vertices:
        rec(s, set(), 0)
    return results

def brute(edges):
    edges = set(edges)
    if not edges:
        return 0
