    for u, v in edges:
        verts.add(u); verts.add(v)
    # weak components (undirected)
    comps = []
    unseen = set(verts)
    while unseen:
        s = unseen.pop()
        comp = {s}; dq = deque([s])
        while dq:
            x = dq.popleft()
            for (u, v) in edges:
                if x in (u, v):
                    y = v if x == u else u
                    if y not in comp:
                        comp.add(y); dq.append(y); unseen.discard(y)
        comps.append(comp)
    # per component brute force via set cover over walk coverages restricted to component
    total = 0
    for comp in comps:
